import { OrderService } from "../application/order-service";
import { createApp } from "./http-app";
import { InMemoryOrderRepository, InMemoryProductRepository } from "./in-memory-repositories";

const products = new InMemoryProductRepository([
  { id: "widget", name: "Widget", onHand: 100, reserved: 0 },
  { id: "gadget", name: "Gadget", onHand: 50, reserved: 0 },
  { id: "gizmo", name: "Gizmo", onHand: 10, reserved: 0 },
]);

const service = new OrderService(products, new InMemoryOrderRepository());
const port = Number(process.env.PORT ?? 3000);

createApp(service).listen(port, () => {
  console.log(`Order fulfilment API listening on port ${port}`);
});

